arguments.new_string:
export interface AuthEnv {
  DB: D1Database;
  BETTER_AUTH_SECRET: string;
  MIGRATION_SECRET?: string;
  BETTER_AUTH_URL: string;
  PUBLIC_GAME_URL: string;
  BETTER_AUTH_TRUSTED_ORIGINS?: string;
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  GITHUB_CLIENT_ID?: string;
  GITHUB_CLIENT_SECRET?: string;
}

/**
 * The only providers `/cli/oauth` will start a sign-in for. Anything else is a
 * typo or someone probing the endpoint, so it gets a 400 rather than being
 * forwarded to better-auth (which knows dozens of providers we never configured).
 */
export const CLI_OAUTH_PROVIDERS = ["google", "github"] as const;

export type CliOAuthProvider = (typeof CLI_OAUTH_PROVIDERS)[number];

export function isCliOAuthProvider(value: string | null): value is CliOAuthProvider {
  return value !== null && (CLI_OAUTH_PROVIDERS as readonly string[]).includes(value);
}

/**
 * The credentials for one provider, or null when this deployment has not been
 * given them. Sign-in has to fail loudly (503) in that case: better-auth would
 * otherwise build an authorize URL with an empty `client_id` and the user would
 * land on the provider's own error page with nothing to act on.
 */
export function providerCredentials(
  env: AuthEnv,
  provider: CliOAuthProvider,
): { clientId: string; clientSecret: string } | null {
  const clientId = (provider === "google" ? env.GOOGLE_CLIENT_ID : env.GITHUB_CLIENT_ID) ?? "";
  const clientSecret =
    (provider === "google" ? env.GOOGLE_CLIENT_SECRET : env.GITHUB_CLIENT_SECRET) ?? "";
  if (!clientId || !clientSecret) return null;
  return { clientId, clientSecret };
}

function socialProviders(env: AuthEnv) {
  const providers: Record<string, { clientId: string; clientSecret: string }> = {};
  for (const provider of CLI_OAUTH_PROVIDERS) {
    const credentials = providerCredentials(env, provider);
    if (credentials) providers[provider] = credentials;
  }
  return providers;
}

