// Opens a browser sign-in for one provider and comes back through
// /cli/handoff. A GET so the CLI can hand the URL to a browser as-is.
if (url.pathname === "/cli/oauth" && request.method === "GET") {
  const provider = url.searchParams.get("provider");
  if (!isCliOAuthProvider(provider)) {
    return new Response(
      "Unsupported provider. Use provider=google or provider=github.",
      { status: 400, headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" } },
    );
  }
  if (!providerCredentials(env, provider)) {
    return new Response(
      `${provider} sign-in is not configured on this deployment. Set the ${provider.toUpperCase()}_CLIENT_ID and ${provider.toUpperCase()}_CLIENT_SECRET secrets, or use: gamepigeon auth login`,
      { status: 503, headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" } },
    );
  }
  const target = cliRedirectTarget(url.searchParams.get("next"));
  if (!target) return rejectedNext();

  // The provider redirects back to *this* Worker (where the session cookie
  // lives), and /cli/handoff is what forwards the session to the CLI, so the
  // loopback address travels as `next` on our own callback URL.
  const handoff = new URL("/cli/handoff", env.BETTER_AUTH_URL);
  handoff.searchParams.set("next", target.toString());
  let started: Response;
  try {
    started = await createAuth(env).api.signInSocial({
      body: {
        provider,
        callbackURL: handoff.toString(),
        errorCallbackURL: handoff.toString(),
        // We need the authorize URL in hand so the state cookie better-auth
        // sets rides along on our own redirect.
        disableRedirect: true,
      },
      headers: request.headers,
      asResponse: true,
    });
  } catch {
    return new Response("Could not start sign-in with " + provider + ".", {
      status: 502,
      headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" },
    });
  }
  const payload = (await started.json().catch(() => null)) as { url?: string } | null;
  if (!started.ok || !payload?.url) {
    return new Response(`Could not start sign-in with ${provider}.`, {
      status: 502,
      headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" },
    });
  }
  const headers = new Headers({
    location: payload.url,
    "cache-control": "no-store",
    "referrer-policy": "no-referrer",
  });
  for (const cookie of started.headers.getSetCookie()) headers.append("set-cookie", cookie);
  return new Response(null, { status: 302, headers });
}

// Hands the browser session created by /cli/oauth back to the CLI listener
// waiting on `next`.
if (url.pathname === "/cli/handoff" && request.method === "GET") {
  const target = cliRedirectTarget(url.searchParams.get("next"));
  if (!target) return rejectedNext();

  // A provider that refused — or a user who closed the consent screen —
  // arrives with `error` and no session. The CLI's own listener renders the
  // reason, so forward it instead of reporting the missing session.
  const error = url.searchParams.get("error");
  if (error) {
    const description = url.searchParams.get("error_description");
    return handoffTo(target, {
      error,
      ...(description ? { error_description: description } : {}),
    });
  }

  let signedIn = false;
  try {
    const session = await createAuth(env).api.getSession({ headers: request.headers });
    signedIn = Boolean(session?.user);
  } catch {
    signedIn = false;
  }
  const token = sessionCookieToken(request.headers.get("cookie"));
  if (!signedIn || !token) {
    return new Response(notSignedInPage(), { status: 401, headers: HTML_HEADERS });
  }
  return handoffTo(target, { token });
}

if (url.pathname === "/" && request.method === "GET") {

