import { getMigrations } from "better-auth/db/migration";
import {
  createAuth,
  isCliOAuthProvider,
  providerCredentials,
  trustedOrigins,
  type AuthEnv,
} from "./auth";
import { handoffRedirectPage, notSignedInPage } from "./handoff-page";

// better-auth's default session cookie name, plus the `__Secure-` prefixed form
// it uses when cookies are marked secure (i.e. any https deployment).
const SESSION_COOKIE_NAMES = [
  "better-auth.session_token",
  "__Secure-better-auth.session_token",
];

const HTML_HEADERS = {
  "content-type": "text/html; charset=utf-8",
  // These pages carry a session token in their markup and in the URL they
  // redirect to — keep them out of caches and out of the Referer sent onward.
  "cache-control": "no-store",
  "referrer-policy": "no-referrer",
};

/**
 * The localhost listener a CLI asked us to hand its session to, or null when
 * `next` is anything we are not willing to attach a token to.
 *
 * Only plain-http loopback addresses qualify: the token rides in the query
 * string, so a `next` pointing anywhere else (another host, or an `https` URL
 * whose hostname merely reads as localhost) would be a way to have this Worker
 * mail a live session to a third party. Ports are deliberately unrestricted —
 * the CLI falls back to an OS-assigned port when 3210 is busy.
 */
function cliRedirectTarget(next: string | null): URL | null {
  if (!next) return null;
  let target: URL;
  try {
    target = new URL(next);
  } catch {
    return null;
  }
  if (target.protocol !== "http:") return null;
  if (target.hostname !== "127.0.0.1" && target.hostname !== "localhost") return null;
  return target;
}

function rejectedNext(): Response {
  return new Response(
    "Invalid next: expected a http://127.0.0.1:<port>/... or http://localhost:<port>/... URL.",
    { status: 400, headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" } },
  );
}

/**
 * The literal session cookie value, read from the request's `Cookie` header
 * rather than from whatever `getSession` returns: the token is what the CLI will
 * send back as a bearer credential, and the shape of the session object is not
 * something this route should depend on.
 */
function sessionCookieToken(cookieHeader: string | null): string | null {
  if (!cookieHeader) return null;
  for (const name of SESSION_COOKIE_NAMES) {
    for (const pair of cookieHeader.split(";")) {
      const separator = pair.indexOf("=");
      if (separator < 0) continue;
      if (pair.slice(0, separator).trim() !== name) continue;
      const value = pair.slice(separator + 1).trim();
      if (value) return value;
    }
  }
  return null;
}

/** Sends the browser on to `target`, with `token` appended to whatever query it already had. */
function handoffTo(target: URL, params: Record<string, string>): Response {
  for (const [key, value] of Object.entries(params)) target.searchParams.set(key, value);
  return new Response(handoffRedirectPage(target.toString()), { status: 200, headers: HTML_HEADERS });
}

function authCors(request: Request, response: Response, env: AuthEnv): Response {
  const origin = request.headers.get("origin");
  if (!origin || !trustedOrigins(env).includes(origin)) return response;
  const headers = new Headers(response.headers);
  headers.set("access-control-allow-origin", origin);
  headers.set("access-control-allow-credentials", "true");
  headers.set("access-control-expose-headers", "set-auth-token");
  headers.append("vary", "Origin");
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
}

export default {
  async fetch(request: Request, env: AuthEnv): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname.startsWith("/api/auth/") && request.method === "OPTIONS") {
      const origin = request.headers.get("origin");
      if (!origin || !trustedOrigins(env).includes(origin)) return new Response(null, { status: 403 });
      return authCors(request, new Response(null, {
        status: 204,
        headers: {
          "access-control-allow-headers": "content-type, authorization",
          "access-control-allow-methods": "GET, POST, OPTIONS",
        },
      }), env);
    }

    if (url.pathname === "/migrate" && request.method === "POST") {
      if (
        !env.MIGRATION_SECRET
        || request.headers.get("authorization") !== `Bearer ${env.MIGRATION_SECRET}`
      ) {
        return Response.json(
          { error: "Unauthorized" },
          { status: 401, headers: { "www-authenticate": "Bearer" } },
        );
      }
      const auth = createAuth(env);
      const { toBeCreated, toBeAdded, runMigrations } = await getMigrations(auth.options);
      if (toBeCreated.length === 0 && toBeAdded.length === 0) {
        return Response.json({ message: "No migrations needed" });
      }
      await runMigrations();
      return Response.json({
        message: "Migrations completed",
        created: toBeCreated.map((table) => table.table),
        added: toBeAdded.map((table) => table.table),
      });
    }

    if (url.pathname === "/" && request.method === "GET") {
      return Response.json({
        service: "tui-gamepigeon-auth",
        ok: true,
        authBasePath: "/api/auth",
      });
    }

    return authCors(request, await createAuth(env).handler(request), env);
  },
} satisfies ExportedHandler<AuthEnv>;

