import { getMigrations } from "better-auth/db/migration";
import { env } from "cloudflare:workers";
import { beforeAll, expect, test } from "vitest";
import { createAuth, type AuthEnv } from "../src/auth";
import worker from "../src/index";

const workerEnv = env as unknown as AuthEnv;

function withEnv(overrides: Partial<AuthEnv> = {}): AuthEnv {
  return { ...workerEnv, ...overrides };
}

function fetchWorker(path: string, init: RequestInit = {}, overrides?: Partial<AuthEnv>) {
  const request = new Request(`${workerEnv.BETTER_AUTH_URL}${path}`, init);
  return worker.fetch(request, withEnv(overrides));
}

const configured: Partial<AuthEnv> = {
  GOOGLE_CLIENT_ID: "google-test-client",
  GOOGLE_CLIENT_SECRET: "google-test-secret",
  GITHUB_CLIENT_ID: "github-test-client",
  GITHUB_CLIENT_SECRET: "github-test-secret",
};

const callback = "http://127.0.0.1:3210/auth/callback?state=nonce-1";
const next = encodeURIComponent(callback);

// Every `next` we must refuse: the token rides in the query string, so anything
// that is not plain-http loopback is a way to mail a live session elsewhere.
const untrustedNextTargets = [
  "https://127.0.0.1:3210/auth/callback",
  "http://evil.example/auth/callback",
  "http://127.0.0.1.evil.example/auth/callback",
  "http://user@evil.example/auth/callback",
  "file:///tmp/auth",
  "/auth/callback",
  "",
];

beforeAll(async () => {
  const { runMigrations } = await getMigrations(createAuth(workerEnv).options);
  await runMigrations();
});

/** Signs up a browser user and returns its `better-auth.session_token` cookie pair. */
async function browserSessionCookie(email: string): Promise<string> {
  const response = await fetchWorker("/api/auth/sign-up/email", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ email, password: "correct-horse-battery", name: "Test Person" }),
  });
  expect(response.status).toBe(200);
  const cookie = response.headers
    .getSetCookie()
    .map((value) => value.split(";")[0]!)
    .find((pair) => pair.startsWith("better-auth.session_token="));
  expect(cookie).toBeDefined();
  return cookie!;
}

test("cli oauth start rejects providers other than google and github", async () => {
  for (const provider of ["", "apple", "Google", "generic-oauth"]) {
    const response = await fetchWorker(
      `/cli/oauth?provider=${encodeURIComponent(provider)}&next=${next}`,
      {},
      configured,
    );
    expect(response.status).toBe(400);
    expect(await response.text()).toMatch(/provider/i);
  }
});

test("cli oauth start reports an unconfigured provider as unavailable", async () => {
  for (const provider of ["google", "github"]) {
    const response = await fetchWorker(`/cli/oauth?provider=${provider}&next=${next}`);
    expect(response.status).toBe(503);
    expect(await response.text()).toContain(`${provider.toUpperCase()}_CLIENT_ID`);
  }
});

test("cli oauth start refuses to send a token anywhere but loopback http", async () => {
  for (const target of untrustedNextTargets) {
    const response = await fetchWorker(
      `/cli/oauth?provider=google&next=${encodeURIComponent(target)}`,
      {},
      configured,
    );
    expect(response.status).toBe(400);
  }
});

test("cli oauth start redirects to the provider and comes back through the handoff", async () => {
  const response = await fetchWorker(`/cli/oauth?provider=google&next=${next}`, {}, configured);
  expect(response.status).toBe(302);
  const location = new URL(response.headers.get("location")!);
  expect(location.origin).toBe("https://accounts.google.com");
  expect(location.searchParams.get("client_id")).toBe("google-test-client");
  const redirectUri = location.searchParams.get("redirect_uri")!;
  expect(redirectUri).toBe(`${workerEnv.BETTER_AUTH_URL}/api/auth/callback/google`);
  // The oauth state better-auth just issued has to travel with our redirect.
  expect(response.headers.getSetCookie().join(" ")).toMatch(/state/);
});

test("cli handoff without a browser session asks for the oauth command", async () => {
  const response = await fetchWorker(`/cli/handoff?next=${next}`);
  expect(response.status).toBe(401);
  expect((await response.text()).toLowerCase()).toContain("oauth");
});

test("cli handoff validates next before it looks at the session", async () => {
  const cookie = await browserSessionCookie("handoff-untrusted@example.com");
  for (const target of untrustedNextTargets) {
    const response = await fetchWorker(
      `/cli/handoff?next=${encodeURIComponent(target)}`,
      { headers: { cookie } },
      configured,
    );
    expect(response.status).toBe(400);
  }
});

test("cli handoff appends the session cookie token to the waiting listener's query", async () => {
  const cookie = await browserSessionCookie("handoff-success@example.com");
  const token = cookie.slice("better-auth.session_token=".length);
  const response = await fetchWorker(`/cli/handoff?next=${next}`, { headers: { cookie } });

  expect(response.status).toBe(200);
  expect(response.headers.get("cache-control")).toBe("no-store");
  expect(response.headers.get("content-type")).toContain("text/html");

  const body = await response.text();
  const expected = new URL(callback);
  expected.searchParams.set("token", token);
  // The un-escaped URL has to be in the page verbatim, so the redirect carries
  // the real token rather than an HTML-escaped copy of it.
  expect(body).toContain(`location.replace(${JSON.stringify(expected.toString())})`);
  expect(expected.searchParams.get("state")).toBe("nonce-1");
  expect(body).toContain('<meta http-equiv="refresh"');
});

test("cli handoff forwards a provider error instead of stalling the CLI", async () => {
  const response = await fetchWorker(
    `/cli/handoff?next=${next}&error=access_denied&error_description=User+said+no`,
  );
  expect(response.status).toBe(200);
  const body = await response.text();
  expect(body).toContain("error=access_denied");
  expect(body).toContain("state=nonce-1");
  expect(body).toContain("User+said+no");
});

test("cli routes ignore non-GET methods", async () => {
  for (const path of ["/cli/oauth?provider=google", "/cli/handoff"]) {
    const response = await fetchWorker(path, { method: "POST" }, configured);
    expect(response.status).not.toBe(200);
    expect(response.status).not.toBe(302);
  }
});

