  const { runMigrations } = await getMigrations(createAuth(workerEnv).options);
  await runMigrations();
});

/** Signs up a browser user and returns its `better-auth.session_token` cookie pair. */
async function browserSessionCookie(email: string): Promise<string> {
  const response = await fetchWorker("/api/auth/sign-up/email", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ email, password: "correct-horse-battery", name: "Test Person" }),
  });
  expect(response.status).toBe(200);
  const cookie = response.headers
    .getSetCookie()
    .map((value) => value.split(";")[0]!)
    .find((pair) => pair.startsWith("better-auth.session_token="));
  expect(cookie).toBeDefined();
  return cookie!;
}

test("cli oauth start rejects providers other than google and github", async () => {
  for (const provider of ["", "apple", "Google", "generic-oauth"]) {
    const response = await fetchWorker(
      `/cli/oauth?provider=${encodeURIComponent(provider)}&next=${next}`,
      {},
      configured,
    );
    expect(response.status).toBe(400);
    expect(await response.text()).toMatch(/provider/i);
  }
});

test("cli oauth start reports an unconfigured provider as unavailable", async () => {
  for (const provider of ["google", "github"]) {
    const response = await fetchWorker(`/cli/oauth?provider=${provider}&next=${next}`);
    expect(response.status).toBe(503);
    expect(await response.text()).toContain(`${provider.toUpperCase()}_CLIENT_ID`);
  }
});

test("cli oauth start refuses to send a token anywhere but loopback http", async () => {
  for (const target of untrustedNextTargets) {
    const response = await fetchWorker(
      `/cli/oauth?provider=google&next=${encodeURIComponent(target)}`,
      {},
      configured,
    );
    expect(response.status).toBe(400);
  }
});

test("cli oauth start redirects to the provider and comes back through the handoff", async () => {
  const response = await fetchWorker(`/cli/oauth?provider=google&next=${next}`, {}, configured);
  expect(response.status).toBe(302);
  const location = new URL(response.headers.get("location")!);
  expect(location.origin).toBe("https://accounts.google.com");
  expect(location.searchParams.get("client_id")).toBe("google-test-client");
  const redirectUri = location.searchParams.get("redirect_uri")!;
  expect(redirectUri).toBe(`${workerEnv.BETTER_AUTH_URL}/api/auth/callback/google`);
  // The oauth state better-auth just issued has to travel with our redirect.
  expect(response.headers.getSetCookie().join(" ")).toMatch(/state/);
});

test("cli handoff without a browser session asks for the oauth command", async () => {
  const response = await fetchWorker(`/cli/handoff?next=${next}`);
  expect(response.status).toBe(401);
  expect((await response.text()).toLowerCase()).toContain("oauth");
});

test("cli handoff validates next before it looks at the session", async () => {
  const cookie = await browserSessionCookie("handoff-untrusted@example.com");
  for (const target of untrustedNextTargets) {
    const response = await fetchWorker(
      `/cli/handoff?next=${encodeURIComponent(target)}`,
      { headers: { cookie } },
      configured,
    );
    expect(response.status).toBe(400);
  }
});

test("cli handoff appends the session cookie token to the waiting listener's query", async () => {
  const cookie = await browserSessionCookie("handoff-success@example.com");
  const token = cookie.slice("better-auth.session_token=".length);
  const response = await fetchWorker(`/cli/handoff?next=${next}`, { headers: { cookie } });

  expect(response.status).toBe(200);
  expect(response.headers.get("cache-control")).toBe("no-store");
  expect(response.headers.get("content-type")).toContain("text/html");

  const body = await response.text();
  const expected = new URL(callback);
  expected.searchParams.set("token", token);
  // The un-escaped URL has to be in the page verbatim, so the redirect carries
  // the real token rather than an HTML-escaped copy of it.
  expect(body).toContain(`location.replace(${JSON.stringify(expected.toString())})`);
  expect(expected.searchParams.get("state")).toBe("nonce-1");
  expect(body).toContain('<meta http-equiv="refresh"');
});

test("cli handoff forwards a provider error instead of stalling the CLI", async () => {
  const response = await fetchWorker(
    `/cli/handoff?next=${next}&error=access_denied&error_description=User+said+no`,
  );
  expect(response.status).toBe(200);
  const body = await response.text();
  expect(body).toContain("error=access_denied");
  expect(body).toContain("state=nonce-1");
  expect(body).toContain("User+said+no");
});

test("cli routes ignore non-GET methods", async () => {
  for (const path of ["/cli/oauth?provider=google", "/cli/handoff"]) {
    const response = await fetchWorker(path, { method: "POST" }, configured);
    expect(response.status).not.toBe(200);
    expect(response.status).not.toBe(302);
  }
});

arguments.content:
// The pages the browser lands on at the end of a CLI sign-in, served by the
// localhost listener in `auth.ts`. This is the hand-back point between the
// hosted login page and the terminal, so it confirms the outcome and says
// whether to close the tab.
//
// The same design is rendered by `tauri/src/auth_pages.rs` and
// `cloudflare/auth-worker/src/handoff-page.ts`; the three copies exist because
// they run in three different runtimes. Keep the copy and palette in sync when
// changing one.

const STYLE = `:root{color-scheme:light}
*{box-sizing:border-box}
body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;
background:radial-gradient(900px 500px at 50% -20%,#fff 0%,#eef2f8 60%,#e3eaf4 100%);color:#0f172a;
font:15px/1.6 system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",sans-serif;-webkit-font-smoothing:antialiased}
.card{position:relative;overflow:hidden;width:min(100%,420px);padding:34px 28px 30px;text-align:center;
background:#fff;border:1px solid #e2e8f0;border-radius:16px;
box-shadow:0 20px 50px rgba(15,23,42,.12),0 8px 20px rgba(15,23,42,.06)}
.card::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;
background:linear-gradient(90deg,#2955c9 0%,#3772ff 38%,#3bb273 72%,#e6a830 100%)}
.badge{display:flex;align-items:center;justify-content:center;width:44px;height:44px;margin:0 auto 16px;border-radius:999px}
.badge svg{width:22px;height:22px}
[data-tone=ok] .badge{background:rgba(59,178,115,.14);color:#2e8f5c}
[data-tone=warn] .badge{background:rgba(223,41,53,.12);color:#b81f2a}
.eyebrow{margin:0 0 6px;font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:#2955c9}
h1{margin:0 0 10px;font-size:23px;line-height:1.25;letter-spacing:-.01em}
.lead{margin:0;color:#475569}
.steps{margin:18px 0 0;padding:0;list-style:none;text-align:left;border-top:1px solid #e2e8f0}
.steps li{position:relative;margin:0;padding:10px 0 0 18px;font-size:13.5px;color:#475569}
.steps li:first-child{padding-top:14px}
.steps li::before{content:"";position:absolute;left:2px;top:18px;width:5px;height:5px;border-radius:999px;background:#cbd5e1}
.steps li:first-child::before{top:22px}
.hint{margin:16px 0 0;font-size:12.5px;color:#64748b}
code{font:600 12.5px/1.4 ui-monospace,"SF Mono",Menlo,monospace;background:#f3f6fb;border:1px solid #e2e8f0;border-radius:5px;padding:2px 5px;overflow-wrap:anywhere;-webkit-box-decoration-break:clone;box-decoration-break:clone}
@media (max-width:400px){.card{padding:28px 20px 24px}h1{font-size:21px}}`;

const CHECK_ICON =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>';
const ALERT_ICON =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7.5v5.5"/><path d="M12 16.5h.01"/></svg>';

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/**
 * Renders one self-contained Tui page — no external CSS, fonts, or images.
 *
 * `lead`, `steps`, and `hint` are trusted HTML so copy can carry `<code>`
 * spans; the title is escaped. Escape request-derived text at the call site.
 */
function arcadePage(
  tone: "ok" | "warn",
  title: string,
  lead: string,
  steps: string[],
  hint: string,
): string {
  const list = steps.length
    ? `<ul class="steps">${steps.map((step) => `<li>${step}</li>`).join("")}</ul>`
    : "";
  const hintHtml = hint ? `<p class="hint">${hint}</p>` : "";
  const icon = tone === "ok" ? CHECK_ICON : ALERT_ICON;
  const titleText = escapeHtml(title);
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<title>Tui — ${titleText}</title>
<style>${STYLE}</style>
</head>
<body>
<main class="card" data-tone="${tone}">
<span class="badge">${icon}</span>
<p class="eyebrow">Tui</p>
<h1>${titleText}</h1>
<p class="lead">${lead}</p>
${list}
${hintHtml}
</main>
</body>
</html>`;
}

/** Success: the CLI has the token and is saving the session. */
export function signedInPage(): string {
  return arcadePage(
    "ok",
    "You're signed in",
    "Tui saved this session. You can close this tab and go back to your terminal.",
    [],
    "Your session is saved on this machine, so Tui opens straight to the games next time.",
  );
}

/**
 * The handoff reached us but carried no usable session. `reason` is inserted as
 * trusted HTML — escape request-derived text before calling.
 */
export function signInFailedPage(reason: string): string {
  return arcadePage(
    "warn",
    "Sign-in didn't finish",
    reason,
    [
      "Go back to your terminal and run <code>gamepigeon auth oauth google</code> or <code>gamepigeon auth oauth github</code> again.",
      "If your browser blocked the redirect back to Tui, allow pop-ups for the login page.",
      "Signing in with Google or GitHub? Approve the consent screen rather than closing it.",
    ],
    "Prefer email and password? <code>gamepigeon auth login</code> signs in the same account.",
  );
}

