/**
 * The localhost listener a browser sign-in hands its token back to.
 *
 * Returns synchronously so the caller can read `port` off the handle it is
 * building the login URL from; `ready` is what tells you the socket is bound
 * (and, after a port fallback, that `port` is final).
 */
export interface OAuthCallbackServer {
  readonly port: number;
  ready: Promise<void>;
  token: Promise<string>;
  close(): void;
}

export function startOAuthCallbackServer(port: number): OAuthCallbackServer {
  let settle: ((token: string) => void) | null = null;
  let fail: ((error: Error) => void) | null = null;
  const token = new Promise<string>((resolve, reject) => {
    // Only the first callback counts: a stale tab arriving later must not
    // overwrite the session we already accepted.
    settle = (value) => {
      const done = settle !== null;
      settle = null;
      fail = null;
      if (done) resolve(value);
    };
    fail = (error) => {
      settle = null;
      fail = null;
      reject(error);
    };
  });

