        "content-length": Buffer.byteLength(body),
        // The callback URL carries a session token — keep the page out of
        // caches and out of the Referer sent to anything it links to.
        "cache-control": "no-store",
        "referrer-policy": "no-referrer",
        connection: "close",
      });
