function isOAuthProvider(value: string): value is OAuthProvider {
  return (oauthProviders as readonly string[]).includes(value);
}

async function awaitCallbackToken(callback: OAuthCallbackServer): Promise<string> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      callback.token,
      new Promise<never>((_resolve, reject) => {
        timer = setTimeout(
          () => reject(new Error("Sign-in timed out. Try again.")),
          oauthTimeoutMs,
        );
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
    // When the timeout wins, nothing is left to observe a later rejection from
    // the listener itself.
    callback.token.catch(() => {});
  }
}

