 * round trip and `/cli/handoff` redirects back to the listener below with a
 * session token. The state nonce rides along only so the Worker's redirect keeps
 * it — the listener has nothing to compare it against.
 */
async function runOAuthLogin(provider: OAuthProvider): Promise<AuthSuccess> {
  const authBaseUrl = requireAuthBaseUrl();
  const callback = startOAuthCallbackServer(defaultCallbackPort);
  try {
    await callback.ready;
    const next = `http://${callbackHost}:${callback.port}/auth/callback?state=${randomBytes(16).toString("hex")}`;
    const url = `${authBaseUrl}/cli/oauth?provider=${provider}&next=${encodeURIComponent(next)}`;
    const label = oauthProviderLabels[provider];
    if (openBrowser(url)) {
      console.log(`Opening your browser to sign in with ${label}...`);
    } else {
      console.log(`Could not open a browser automatically.`);
    }
    console.log(`If nothing opens, paste this into your browser:\n  ${url}`);

    const token = await awaitCallbackToken(callback);
    const user = await resolveUser(token);
    saveSession(token, user);
    console.log(`Signed in as ${user.email}`);
    return { kind: "signed_in", method: provider, userId: user.id };
  } finally {
    callback.close();
  }
}

export type { AuthUser, StoredSession };

