// Tolerant of both `&` and `?` separators: some hosted redirects append `?token`
// onto a callback that already carried `?state`, yielding `state=..?token=..`.
function queryParam(query: string, key: string): string | null {
  for (const pair of query.split(/[&?]/)) {
    const separator = pair.indexOf("=");
    if (separator < 0) continue;
    if (pair.slice(0, separator) !== key) continue;
    return pair.slice(separator + 1).replace(/\+/g, " ");
  }
  return null;
}

// Percent-decoding for human-readable query text (OAuth error descriptions).
// Tokens deliberately skip this: they round-trip through the listener verbatim.
// Malformed escapes are left alone rather than throwing — this text only exists
// to be shown to someone.
function percentDecode(value: string): string {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

// Turns a failed handoff (`?error=...`) into a sentence worth showing. Capped
// because it lands in both the browser page and the terminal.
function callbackFailure(query: string): string | null {
  const error = queryParam(query, "error");
  if (!error) return null;
  if (error === "access_denied") return "Sign-in was cancelled before it finished.";
  const description = percentDecode(queryParam(query, "error_description") ?? "");
  const message = description
    ? description
    : `The login page reported an error: ${percentDecode(error)}`;
  return message.slice(0, 200);
}

/**
 * The localhost listener a browser sign-in hands its token back to.
 *
 * Returns synchronously so the caller can read `port` off the handle it is
 * building the login URL from; `ready` is what tells you the socket is bound
 * (and, after a port fallback, that `port` is final).
 */
export interface OAuthCallbackServer {
  readonly port: number;
  ready: Promise<void>;
  token: Promise<string>;
  close(): void;
}

export function startOAuthCallbackServer(port: number): OAuthCallbackServer {
  let settle: ((token: string) => void) | null = null;
  let fail: ((error: Error) => void) | null = null;
  const token = new Promise<string>((resolve, reject) => {
    // Only the first callback counts: a stale tab arriving later must not
    // overwrite the session we already accepted.
    settle = (value) => {
      const done = settle !== null;
      settle = null;
      fail = null;
      if (done) resolve(value);
    };
    fail = (error) => {
      settle = null;
      fail = null;
      reject(error);
    };
  });

  const server = createServer((request, response) => {
    const reply = (status: number, contentType: string, body: string) => {
      response.writeHead(status, {
        "content-type": contentType,
        "content-length": Buffer.byteLength(body),
        // The callback URL carries a session token — keep the page out of
        // caches and out of the Referer sent to anything it links to.
        "cache-control": "no-store",
        "referrer-policy": "no-referrer",
        connection: "close",
      });
      response.end(body);
    };

    const target = request.url ?? "/";
    const separator = target.indexOf("?");
    const path = separator < 0 ? target : target.slice(0, separator);
    const query = separator < 0 ? "" : target.slice(separator + 1);

    // The hosted login page probes this before redirecting, to check we're up.
    if (path === "/auth/ping") {
      reply(200, "text/plain; charset=utf-8", "ok");
      return;
    }
    if (path !== "/auth/callback") {
      reply(404, "text/plain; charset=utf-8", "not found");
      return;
    }
    // A login page that gave up hands back `error` instead of `token`; saying
    // why beats the generic "did not return a session token".
    const failure = callbackFailure(query);
    if (failure) {
      reply(400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(failure)));
      fail?.(new Error(failure));
      return;
    }
    const value = queryParam(query, "token");
    if (value) {
      reply(200, "text/html; charset=utf-8", signedInPage());
      settle?.(value);
      return;
    }
    const reason = "The login page came back without a session token.";
    reply(400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(reason)));
    fail?.(new Error(reason));
  });

  let boundPort = port;
  const ready = new Promise<void>((resolve, reject) => {
    server.once("listening", () => {
      const address = server.address();
      if (address && typeof address === "object") boundPort = address.port;
      resolve();
    });
    // 3210 is the port the Worker trusts by default, but a second CLI (or the
    // overlay) may already hold it, so one retry falls back to any free port.
    server.once("error", (error: NodeJS.ErrnoException) => {
      if (error.code !== "EADDRINUSE") {
        reject(error);
        return;
      }
      server.once("error", reject);
      server.listen(0, callbackHost);
    });
    server.listen(port, callbackHost);
  });

  return {
    get port() {
      return boundPort;
    },
    ready,
    token,
    close() {
      server.closeAllConnections?.();
      server.close();
    },
  };
}

/** Runs an opener and reports whether it actually succeeded, not just spawned. */
function runOpener(command: string, args: string[]): boolean {
  try {
    const result = spawnSync(command, args, { stdio: "ignore" });
    return !result.error && result.status === 0;
  } catch {
    return false;
  }
}

function applescriptEscape(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

/**
 * Arc (and Dia, same vendor) route links from other apps into a "Little Arc"
 * window, which drops the hosted login page's redirect chain — the tab either
 * never appears or dies mid-handoff, so sign-in silently never completes.
 * Asking Arc for a real tab in a real window over AppleScript bypasses Little
 * Arc entirely. Mirrors `is_arc_bundle`/`open_in_arc` in `tauri/src/main.rs`.
 */
export function isArcBundle(bundleId: string): boolean {
  const id = bundleId.toLowerCase();
  return id === "company.thebrowser.browser" || id === "company.thebrowser.dia";
}

export function arcTabScript(bundleId: string, url: string): string {
  return `tell application id "${applescriptEscape(bundleId)}"
    activate
    if (count of windows) is 0 then
        make new window
    end if
    tell front window to make new tab with properties {URL:"${applescriptEscape(url)}"}
end tell`;
}

/**
 * `defaults read` prints one dict per registered handler; the role and the
 * scheme are separate lines inside the same `{ ... }` block, so we scan block
 * by block for the one claiming `https`.
 */
function parseDefaultHttpsHandler(plist: string): string | null {
  for (const block of plist.split("{")) {
    if (!block.includes("LSHandlerURLScheme = https;")) continue;
    const line = block
      .split("\n")
      .find((candidate) => candidate.trimStart().startsWith("LSHandlerRoleAll = "));
    if (!line) return null;
    const value = line.trim().slice("LSHandlerRoleAll = ".length).replace(/;$/, "").replace(/^"|"$/g, "");
    if (value) return value;
  }
  return null;
}

/**
 * The bundle id macOS would hand an `https` URL to, read from LaunchServices.
 * Used only to detect Arc; any parse failure just means we take the ordinary
 * `open` path.
 */
function defaultHttpsHandler(): string | null {
  const result = spawnSync(
    "defaults",
    ["read", "com.apple.LaunchServices/com.apple.launchservices.secure"],
    { encoding: "utf8" },
  );
  if (result.error || result.status !== 0 || !result.stdout) return null;
  return parseDefaultHttpsHandler(result.stdout);
}

/**
 * Hands the login URL to the user's browser. Returns false when every opener we
 * know about failed — the caller then leads with the pasteable link instead of
 * claiming a browser is opening.
 */
function openBrowser(url: string): boolean {
  if (process.platform === "darwin") {
    const bundleId = defaultHttpsHandler();
    if (bundleId && isArcBundle(bundleId) && runOpener("osascript", ["-e", arcTabScript(bundleId, url)])) {
      return true;
    }
    // Safari is the last resort: it is always present, so a broken or missing
    // default handler still gets the user to the login page.
    return runOpener("open", [url]) || runOpener("open", ["-a", "Safari", url]);
  }
  if (process.platform === "win32") {
    return (
      runOpener("cmd", ["/c", "start", "", url])
      || runOpener("rundll32", ["url.dll,FileProtocolHandler", url])
    );
  }
  return (
    runOpener("xdg-open", [url])
    || runOpener("gio", ["open", url])
    || runOpener("x-www-browser", [url])
  );
}

function isOAuthProvider(value: string): value is OAuthProvider {
  return (oauthProviders as readonly string[]).includes(value);
}

async function awaitCallbackToken(callback: OAuthCallbackServer): Promise<string> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      callback.token,
      new Promise<never>((_resolve, reject) => {
        timer = setTimeout(
          () => reject(new Error("Sign-in timed out. Try again.")),
          oauthTimeoutMs,
        );
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
    // When the timeout wins, nothing is left to observe a later rejection from
    // the listener itself.
    callback.token.catch(() => {});
  }
}

/**
 * Signs in through the browser: the Worker's `/cli/oauth` starts the provider
 * round trip and `/cli/handoff` redirects back to the listener below with a
 * session token. The state nonce rides along only so the Worker's redirect keeps
 * it — the listener has nothing to compare it against.
 */
async function runOAuthLogin(provider: OAuthProvider): Promise<AuthSuccess> {
  const authBaseUrl = requireAuthBaseUrl();
  const callback = startOAuthCallbackServer(defaultCallbackPort);
  try {
    await callback.ready;
    const next = `http://${callbackHost}:${callback.port}/auth/callback?state=${randomBytes(16).toString("hex")}`;
    const url = `${authBaseUrl}/cli/oauth?provider=${provider}&next=${encodeURIComponent(next)}`;
    const label = oauthProviderLabels[provider];
    if (openBrowser(url)) {
      console.log(`Opening your browser to sign in with ${label}...`);
    } else {
      console.log(`Could not open a browser automatically.`);
    }
    console.log(`If nothing opens, paste this into your browser:\n  ${url}`);

    const token = await awaitCallbackToken(callback);
    const user = await resolveUser(token);
    saveSession(token, user);
    console.log(`Signed in as ${user.email}`);
    return { kind: "signed_in", method: provider, userId: user.id };
  } finally {
    callback.close();
  }
}

export type { AuthUser, StoredSession };

