cat >> src/auth.test.ts <<'EOF'
test("callback listener answers the readiness probe and hands back the raw token", async () => {
  const callback = startOAuthCallbackServer(0);
  // The handle is available before the socket is bound; `ready` is the signal.
  expect(callback).not.toBeInstanceOf(Promise);
  try {
    await callback.ready;
    expect(callback.port).toBeGreaterThan(0);

    const ping = await fetch(`http://127.0.0.1:${callback.port}/auth/ping`);
    expect(ping.status).toBe(200);
    expect(await ping.text()).toBe("ok");

    const missing = await fetch(`http://127.0.0.1:${callback.port}/nope`);
    expect(missing.status).toBe(404);

    // `?state=..?token=..` is what a redirect that glues token onto an existing
    // state param produces; the token still has to come through verbatim.
    const done = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?state=nonce-1?token=sess.abc-123`,
    );
    expect(done.status).toBe(200);
    expect(done.headers.get("cache-control")).toBe("no-store");
    expect(done.headers.get("content-type")).toContain("text/html");
    expect(await done.text()).toContain("You&#39;re signed in");
    await expect(callback.token).resolves.toBe("sess.abc-123");
  } finally {
    callback.close();
  }
});

test("callback listener falls back to a free port when the requested one is busy", async () => {
  const holder = startOAuthCallbackServer(0);
  await holder.ready;
  const busy = holder.port;
  const callback = startOAuthCallbackServer(busy);
  try {
    await callback.ready;
    expect(callback.port).not.toBe(busy);
    expect(callback.port).toBeGreaterThan(0);
    const ping = await fetch(`http://127.0.0.1:${callback.port}/auth/ping`);
    expect(ping.status).toBe(200);
  } finally {
    callback.close();
    holder.close();
  }
});

test("a cancelled sign-in fails the callback with a reason the page repeats", async () => {
  const callback = startOAuthCallbackServer(0);
  try {
    await callback.ready;
    const response = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?state=nonce-1&error=access_denied`,
    );
    expect(response.status).toBe(400);
    expect(response.headers.get("cache-control")).toBe("no-store");
    expect(await response.text()).toMatch(/cancelled/i);
    await expect(callback.token).rejects.toThrow(/cancelled/i);
  } finally {
    callback.close();
  }
});

test("a provider error is escaped in the page but raw in the thrown message", async () => {
  const callback = startOAuthCallbackServer(0);
  try {
    await callback.ready;
    const description = "<script>alert(1)</script> is not allowed";
    const response = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?error=server_error&error_description=${encodeURIComponent(description)}`,
    );
    expect(response.status).toBe(400);
    const body = await response.text();
    expect(body).not.toContain("<script>alert(1)</script>");
    expect(body).toContain("&lt;script&gt;alert(1)&lt;/script&gt;");
    await expect(callback.token).rejects.toThrow(description);
  } finally {
    callback.close();
  }
});

test("a callback with no token at all is reported rather than left hanging", async () => {
  const callback = startOAuthCallbackServer(0);
  try {
    await callback.ready;
    const response = await fetch(`http://127.0.0.1:${callback.port}/auth/callback?state=nonce-1`);
    expect(response.status).toBe(400);
    expect(await response.text()).toContain("without a session token");
    await expect(callback.token).rejects.toThrow(/session token/);
  } finally {
    callback.close();
  }
});

test("arc and dia links go through applescript, other browsers do not", () => {
  expect(isArcBundle("company.thebrowser.Browser")).toBe(true);
  expect(isArcBundle("company.thebrowser.dia")).toBe(true);
  expect(isArcBundle("com.apple.Safari")).toBe(false);
  expect(isArcBundle("com.google.Chrome")).toBe(false);

  const script = arcTabScript("company.thebrowser.Browser", "https://auth.example/cli/oauth?a=1&b=2");
  expect(script).toContain('tell application id "company.thebrowser.Browser"');
  // A real tab in a real window, which is what Little Arc would not give us.
  expect(script).toContain("make new window");
  expect(script).toContain('tell front window to make new tab with properties {URL:"https://auth.example/cli/oauth?a=1&b=2"}');

  // Quotes and backslashes in either argument stay inside their literal.
  const escaped = arcTabScript('a"b\\c', 'http://x/?q="1"');
  expect(escaped).toContain('tell application id "a\\"b\\\\c"');
  expect(escaped).toContain('{URL:"http://x/?q=\\"1\\""}');
});

test("oauth needs a provider we actually support", async () => {
  process.env.GAMEPIGEON_AUTH_URL = "https://auth.example";
  await expect(runAuthCommand("oauth")).rejects.toThrow(/google\|github/);
  await expect(runAuthCommand("oauth", "twitter")).rejects.toThrow(/google\|github/);
});
EOF
