// Tolerant of both `&` and `?` separators: some hosted redirects append `?token`
// onto a callback that already carried `?state`, yielding `state=..?token=..`.
function queryParam(query: string, key: string): string | null {
  for (const pair of query.split(/[&?]/)) {
    const separator = pair.indexOf("=");
    if (separator < 0) continue;
    if (pair.slice(0, separator) !== key) continue;
    return pair.slice(separator + 1).replace(/\+/g, " ");
  }
  return null;
}

