function parseDefaultHttpsHandler(plist: string): string | null {
  for (const block of plist.split("{")) {
    if (!block.includes("LSHandlerURLScheme = https;")) continue;
    const line = block
      .split("\n")
      .find((candidate) => candidate.trimStart().startsWith("LSHandlerRoleAll = "));
    if (!line) return null;
    const value = line.trim().slice("LSHandlerRoleAll = ".length).replace(/;$/, "").replace(/^"|"$/g, "");
